head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageItemCnt = 5; // 페이지당 행 수
scwin.pageIndex = 1; // 현재 페이지 번호
scwin.curDate = ""; // 서버 기준 현재 일자(yyyyMMdd) — onpageload 에서 설정

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    try {
scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

        id_com.setStyle("display", "none");
        tbx_isur_nm1.setFocus();

        // 조회 기간 기본 1년
        cal_std_cd_grnt_start_dd.setValue($c.date.addMonth(scwin.curDate, -12));
        cal_std_cd_grnt_end_dd.setValue(scwin.curDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINF20000.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.btn_3mon_onclick = function (e) {
    try {
        let endDate = cal_std_cd_grnt_end_dd.getValue();
        cal_std_cd_grnt_start_dd.setValue($c.date.addDate(endDate, -90));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINF20000.btn_3mon_onclick" });
    }
};

scwin.btn_6mon_onclick = function (e) {
    try {
        let endDate = cal_std_cd_grnt_end_dd.getValue();
        cal_std_cd_grnt_start_dd.setValue($c.date.addDate(endDate, -181));	
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINF20000.btn_6mon_onclick" });
    }
};

scwin.btn_1year_onclick = function (e) {
	try {
		let endDate = cal_std_cd_grnt_end_dd.getValue();
	    cal_std_cd_grnt_start_dd.setValue($c.date.addDate(endDate, -365));
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDINF20000.btn_1year_onclick" });
	}
};

scwin.btn_3year_onclick = function (e) {
	try {
		let endDate = cal_std_cd_grnt_end_dd.getValue();
	    cal_std_cd_grnt_start_dd.setValue($c.date.addDate(endDate, -1095));
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDINF20000.btn_3year_onclick" });
	}
};

scwin.btn_cdPop_onclick = async function (e) {
    try {
        let url = "/ui/inf/comm/ULDINF90400.xml";
        let popTitle = "발행기관명검색";

        let param = {
            com_nm : tbx_com_nm1.getValue() ,
            isurCd : tbx_isur_cd1.getValue()
        };
        const opts = {
            id: "ULDINF90400",
            popupName: popTitle,
            width: 900,
            height: 679,
            frameModal: "top",
        };
        const rtn = await $c.win.openPopup(url, opts, param);
        /*
            isurCd : isurCd,
            comNm : comNm,
            cntrIsoCd : cntrIsoCd,
            domFornStkcertTpCd : domFornStkcertTpCd,
            fornComYn : fornComYn
        */
        console.log(rtn);
        tbx_com_nm1.setValue(rtn.comNm);
        tbx_isur_cd1.setValue(rtn.isurCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINF20000.btn_cdPop_onclick" });
    }
};

scwin.rdo_gubunRadio_onviewchange = function (info) {
    try {
        scwin.cgSearch();	
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINF20000.rdo_gubunRadio_onviewchange" });
    }
};

scwin.tbx_isur_nm1_oneditenter = function (e) {
	try {
		scwin.search('1');
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDINF20000.tbx_isur_nm1_oneditenter" });
	}
};

scwin.btn_search_onclick = async function (e) {
    try {
        scwin.search('1');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINF20000.btn_search_onclick" });
    }
};

scwin.pgl_pageList_onviewchange = function (info) {
    try {
        console.log(info);
        scwin.pageIndex = info.newSelectedIndex;
        scwin.search(info.newSelectedIndex);
        pgl_pageList.setSelectedIndex(info.newSelectedIndex);	
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINF20000.pgl_pageList_onviewchange" });
    }
};

scwin.grd_dataTb_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        let mktNm = dlt_main.getCellData(rowIndex, "mktNm");

        if(columnId === "stdCd") {
            if (mktNm !== "14" && mktNm !== "15" && mktNm !== "17") {
                let url = "";
                let popTitle = "";

                if(mktNm === "1") {

                } else if (mktNm === "2") {
                    url = "/ui/inf/srch/ULDINF91000.xml";
                    popTitle = "주권 상세정보";
                } else if (mktNm === "3") {
                    url = "/ui/inf/srch/ULDINF91100.xml";
                    popTitle = "채권 상세정보";
                } else if (mktNm === "4") {
                    url = "/ui/inf/srch/ULDINF91400.xml";
                    popTitle = "수익증권 상세정보";
                } else if (mktNm === "5") {
                    url = "/ui/inf/srch/ULDINF91500.xml";
                    popTitle = "신주인수권증권 상세정보";
                } else if (mktNm === "55") {
                    url = "/ui/inf/srch/ULDINF91600.xml";
                    popTitle = "신주인수권증서 상세정보";
                } else if (mktNm === "6") {
                    url = "/ui/inf/srch/ULDINF91800.xml";
                    popTitle = "양도성예금증서(CD) 상세정보";
                } else if (mktNm === "7") {
                    url = "/ui/inf/srch/ULDINF92000.xml";
                    popTitle = "CP 상세정보";
                } else if (mktNm === "77") {
                    url = "/ui/inf/srch/ULDINF91900.xml";
                    popTitle = "전자단기사채 상세정보";
                } else if (mktNm === "8") {
                    url = "/ui/inf/srch/ULDINF92100.xml";
                    popTitle = "유가증권예탁증서(DR) 상세정보";
                } else if (mktNm === "9") {
                    url = "/ui/inf/srch/ULDINF92300.xml";
                    popTitle = "스트립 상세정보";
                } else if (mktNm === "101") {
                    url = "/ui/inf/srch/ULDINF91200.xml";
                    popTitle = "ELS/DLS/ELB/DLB 상세정보";
                } else if (mktNm === "102") {
                    url = "/ui/inf/srch/ULDINF91200.xml";
                    popTitle = "ELS/DLS/ELB/DLB 상세정보";
                } else if (mktNm === "103") {
                    url = "/ui/inf/srch/ULDINF91200.xml";
                    popTitle = "ELS/DLS/ELB/DLB 상세정보";
                } else if (mktNm === "104") {
                    url = "/ui/inf/srch/ULDINF91200.xml";
                    popTitle = "ELS/DLS/ELB/DLB 상세정보";
                } else if (mktNm === "11") {
                    url = "/ui/inf/srch/ULDINF91700.xml";
                    popTitle = "주식워런트(ELW) 상세정보";
                } else if (mktNm === "12" || mktNm === "122") {
                    url = "/ui/inf/srch/ULDINF91300.xml";
                    popTitle = "선물옵션 상세정보";
                } else if (mktNm === "13") {
                    url = "/ui/inf/srch/ULDINF92200.xml";
                    popTitle = "지표 상세정보";
                } else if (mktNm === "14" || mktNm === "16") {
                    url = "/ui/inf/srch/ULDINF92400.xml";
                    popTitle = "ETN 상세정보";
                } else if (mktNm === "15" || mktNm === "18") {
                    url = "/ui/inf/srch/ULDINF92500.xml";
                    popTitle = "투자계약증권 상세정보";
                }
                /*
                else if (mktNm == "16") {
                    dlt_main.setCellData(i, "mktNm2", "ETN");
                } else if (mktNm == "17") {
                    dlt_main.setCellData(i, "mktNm2", "배출권");
                } else if (mktNm == "18") {
                    dlt_main.setCellData(i, "mktNm2", "투자계약증권");
                }
                */
                let param = {
                    mktNm : dlt_main.getCellData(rowIndex, "mktNm"),
                    stdCd : dlt_main.getCellData(rowIndex, "stdCd")
                };
                const opts = {
                    id: "",
                    popupName: popTitle,
                    width: 1000,
                    height: 950,
                    frameModal: "top",
                };
                // var rtn = await $c.win.openPopup(url, opts, param);
                $c.win.openPopup(url, opts, param);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINF20000.grd_dataTb_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// Function /////////

// 조회 처리
scwin.search = async function (index){

	// var gubun = $("input[name='gubunRadio']:radio:checked").val();
    let gubun = rdo_gubunRadio.getValue();
    const isurNm1 = tbx_isur_nm1.getValue();
    const isurByte = WebSquare.util.getStringByteSize(isurNm1);
    const comNm1 = tbx_com_nm1.getValue();
    const isurCd1 = tbx_isur_cd1.getValue();

	if(gubun === "1"){
		if(isurNm1 === ""){
			$c.win.alert("한글종목명 및 표준코드을 입력하세요.");
			tbx_isur_nm1.setFocus();
			return;
		}
		if(isurByte <= 2){
			$c.win.alert("한글종목명 및 표준코드을 확인하세요");
			tbx_isur_nm1.setFocus();
			return;
		}

        dma_search.set("isurNm", tbx_isur_nm1.getValue());
	}else if(gubun === "2"){
		if(comNm1 === ""){
			$c.win.alert("발행기관을 선택하세요.");
			return;
		}		

        dma_search.set("isurCd", tbx_isur_cd1.getValue());
        dma_search.set("comNm", tbx_com_nm1.getValue());

	}

    dma_search.set("page", index);
    dma_search.set("size", scwin.pageItemCnt);

    const sbmOptions = {
        id : "sbm_search",
        action : "/api/isin/search/stdCode/select-list-paging",
        method : "get",
        ref : "dma_search",
        target : "dlt_main=body.content",
        gridview : "grd_dataTb",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.sbm_search_submitdone(sbmRtn);

};

scwin.sbm_search_submitdone = function (e) {

    console.log(e.responseJSON);

    const totalCount = e.responseJSON.body.totalCount;
    const tatalPage = $c.num.ceil(totalCount / scwin.pageItemCnt);
    panel_page.setValue(totalCount);
    pgl_pageList.setCount(tatalPage);
    pgl_pageList.setSelectedIndex(scwin.pageIndex);

    dlt_main.setBroadcast(false);
    for(let i = 0; i < dlt_main.getRowCount(); i++) {
        let mktNm = dlt_main.getCellData(i, "mktNm");
        const listStatCd = dlt_main.getCellData(i, "listStatCd");

        if(mktNm === "1") {

        } else if (mktNm === "2") {
            dlt_main.setCellData(i, "mktNm2", "주권");
        } else if (mktNm === "3") {
            dlt_main.setCellData(i, "mktNm2", "채권");
        } else if (mktNm === "4") {
            dlt_main.setCellData(i, "mktNm2", "수익증권");
        } else if (mktNm === "5") {
            dlt_main.setCellData(i, "mktNm2", "신주인수권증권");
        } else if (mktNm === "55") {
            dlt_main.setCellData(i, "mktNm2", "신주인수권증서");
        } else if (mktNm === "6") {
            dlt_main.setCellData(i, "mktNm2", "CD");
        } else if (mktNm === "7") {
            dlt_main.setCellData(i, "mktNm2", "CP");
        } else if (mktNm === "77") {
            dlt_main.setCellData(i, "mktNm2", "전자단기사채");
        } else if (mktNm === "8") {
            dlt_main.setCellData(i, "mktNm2", "예탁증서");
        } else if (mktNm === "9") {
            dlt_main.setCellData(i, "mktNm2", "스트립")            
        } else if (mktNm === "101") {
            dlt_main.setCellData(i, "mktNm2", "ELS");            
        } else if (mktNm === "102") {
            dlt_main.setCellData(i, "mktNm2", "DLS");
        } else if (mktNm === "103") {
            dlt_main.setCellData(i, "mktNm2", "ELB");
        } else if (mktNm === "104") {
            dlt_main.setCellData(i, "mktNm2", "DLB");
        } else if (mktNm === "11") {
            dlt_main.setCellData(i, "mktNm2", "주식워런트");
        } else if (mktNm === "12" || mktNm === "122") {
            dlt_main.setCellData(i, "mktNm2", "선물/옵션");
        } else if (mktNm === "13") {
            if(dlt_main.getCellData(i, "stdIndicTpNm") === "" || dlt_main.getCellData(i, "stdIndicTpNm") === null) {
                dlt_main.setCellData(i, "mktNm2", "지표");    
            } else {
                dlt_main.setCellData(i, "mktNm2", dlt_main.getCellData(i, "stdIndicTpNm"));    
            }        
        } else if (mktNm === "14") {
            if(dlt_main.getCellData(i, "prodGrpKorNm") === "" || dlt_main.getCellData(i, "prodGrpKorNm") === null) {
                dlt_main.setCellData(i, "mktNm2", "일반상품(석유)");    
            } else {
                dlt_main.setCellData(i, "mktNm2", dlt_main.getCellData(i, "prodGrpKorNm"));    
            }
        } else if (mktNm === "15") {
            if(dlt_main.getCellData(i, "prodGrpKorNm") === "" || dlt_main.getCellData(i, "prodGrpKorNm") === null) {
                dlt_main.setCellData(i, "mktNm2", "일반상품(금)");    
            } else {
                dlt_main.setCellData(i, "mktNm2", dlt_main.getCellData(i, "prodGrpKorNm"));    
            }
        } else if (mktNm === "16") {
            dlt_main.setCellData(i, "mktNm2", "ETN");
        } else if (mktNm === "17") {
            dlt_main.setCellData(i, "mktNm2", "배출권");
        } else if (mktNm === "18") {
            dlt_main.setCellData(i, "mktNm2", "투자계약증권");
        }

        if(listStatCd === "Y") {
            dlt_main.setCellData(i, "listStatNm", "상장");
        } else if(listStatCd === "N" || listStatCd === "-") {
            dlt_main.setCellData(i, "listStatNm", "비상장");
        } else if(listStatCd === "D") {
            dlt_main.setCellData(i, "listStatNm", "상장폐지");
        } else if(listStatCd === "I") {
            dlt_main.setCellData(i, "listStatNm", "미발행");
        } else if(listStatCd === "Z") {
            dlt_main.setCellData(i, "listStatNm", "기타");
        }
    }
    dlt_main.setBroadcast(true, true);
};

///////// 5. 일반/업무 함수 영역 /////////
// 상품별 조회 항목 변경
scwin.cgSearch = function()  {

    let gubun = rdo_gubunRadio.getValue();

    id_isur.setStyle("display", "none");
    id_com.setStyle("display", "none");
	if(gubun === '1'){
        scwin.curSh = 1;
        id_isur.setStyle("display", "table-row");
        tbx_isur_nm1.setFocus();
	}else if(gubun === '2'){
        scwin.curSh = 1;
        id_com.setStyle("display", "table-row");
	}
};
